(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12+Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.27)*18+Math.sin(x*0.016+t*0.32)*12+Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*10+Math.cos(sy*0.02+t*0.35)*7;
  const w2y = Math.cos(sy*0.022+t*0.38)*10+Math.sin(sx*0.018-t*0.42)*7;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.075,2.1,0.9],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.09,1.8,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.055,2.4,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.11,1.6,1.2],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.065,2.7,0.7],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.085,2.0,1.0],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.1,1.9,0.85],
    [420+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*45,0.07,2.2,1.05]
  ];
  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w; iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    wS+=Math.sin(d*f*1.3-t*sp*0.8+2.1)*w*0.4;
  }
  const act=aS/6.4,inh=iS/6.4,ww=wS/6.4;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.9)+Math.sin(fx*0.028-fy*0.038+t*1.2))/2
    +Math.sin((fx+fy)*0.1+t*2.8)*0.15+Math.sin((fx-fy)*0.08-t*2.2)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.6)+Math.sin(dist*0.035+ang*4.5-t*1.3))*0.35;
  const voro=()=>{
    let md=1e9,md2=1e9;
    for(let i=0;i<12;i++){
      const a=i/12*Math.PI*2+t*0.1;
      const r=80+Math.sin(i*2.3+t*0.4)*40;
      const vx=cx+Math.cos(a)*r,vy=cy+Math.sin(a)*r;
      const d=Math.sqrt((fx-vx)**2+(fy-vy)**2);
      if(d<md){md2=md;md=d}else if(d<md2)md2=d;
    }
    return Math.sin((md2-md)*0.25);
  };
  const voronoi=voro();
  const rd1=Math.tanh((act-inh*0.65+bg*0.25+spiral)*2.5);
  const rd2=Math.tanh((ww+spiral*0.5-voronoi*0.3)*1.8);
  const cross=Math.tanh((rd1*rd2+Math.sin(fx*0.06+fy*0.08+t*1.5)*0.2)*2.0);
  const cell=Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.4)*1.4)*0.25;
  const fine=(Math.sin(fx*0.4+t*3)*Math.sin(fy*0.4-t*2.5))*0.08;
  const blend=cross*0.6+rd1*0.2+cell*0.15+fine*0.05;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[10,30,80],[12,65,105],[18,110,120],
    [30,155,130],[120,175,80],[190,185,55],[210,150,60],
    [195,105,65],[155,60,65],[100,30,55],[50,15,48],[5,10,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const energy=Math.abs(cross),lum=0.75+energy*0.35;
  const edge=Math.abs(cross)>0.65?1.0+energy*0.25:1.0;
  const glow=Math.max(0,energy-0.5)*0.5;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*55)|0)
  ];
}
